'use strict';
// Synthetic fixtures and effects live only in memory: no API, storage or credentials.
const AREAS = [['simular','Simular'],['executar','Executar'],['automacao','Automação'],['historico','Histórico e originais'],['configuracoes','Configurações']];
const TYPES = [['Primary','Capa principal'],['Thumb','Miniatura'],['Backdrop','Fundo'],['Logo','Logotipo'],['People','Pessoas'],['Banner','Banner']];
const BASE = {quality:85,lossless:false,resize:false,dimension:2400,ssim:0.96};
const DEFAULTS = {...BASE,batch:250,reserve:2,quota:512,retention:0,savings:5,kib:10,custom:{}};
const ITEMS = [{id:'viagem',name:'Viagem Sintética',year:'2024',kind:'Filme',lib:'filmes'}, {id:'cidade',name:'Cidade Exemplo',year:'2021',kind:'Filme',lib:'filmes'}, {id:'serie',name:'Série Demonstração',year:'2023',kind:'Série',lib:'series'}, {id:'sem',name:'Ensaio sem imagens',year:'2025',kind:'Filme',lib:'filmes'}];
const FIXTURES = [
  {id:'img-v-capa',item:'viagem',type:'Primary',slot:'Capa principal',fmt:'WebP',dim:'1600 × 2400',source:141,output:125,original:486,state:'converted'},
  {id:'img-v-mini',item:'viagem',type:'Thumb',slot:'Miniatura',fmt:'JPEG',dim:'1280 × 720',source:220,output:84,original:220,state:'source'},
  {id:'img-c-capa',item:'cidade',type:'Primary',slot:'Capa principal',fmt:'WebP',dim:'1600 × 2400',source:92,output:92,original:0,state:'external'},
  {id:'img-c-mini',item:'cidade',type:'Thumb',slot:'Miniatura',fmt:'JPEG',dim:'1280 × 720',source:100,output:97,original:100,state:'filter'},
  {id:'img-s-capa',item:'serie',type:'Primary',slot:'Capa principal',fmt:'JPEG',dim:'1600 × 2400',source:640,output:210,original:640,state:'source'},
  {id:'img-c-fundo',item:'cidade',type:'Backdrop',slot:'Fundo · posição 1',fmt:'JPEG',dim:'3840 × 2160',source:1400,output:450,original:1400,state:'shared',shared:true},
  {id:'img-v-logo',item:'viagem',type:'Logo',slot:'Logotipo',fmt:'PNG',dim:'800 × 310',source:60,output:32,original:60,state:'source'},
  {id:'img-s-banner',item:'serie',type:'Banner',slot:'Banner',fmt:'—',dim:'—',source:0,output:0,original:0,state:'remote'},
  {id:'img-pessoa',item:'viagem',type:'People',slot:'Pessoa Exemplo · foto global',fmt:'JPEG',dim:'900 × 900',source:96,output:58,original:96,state:'source'}
];
const copy = x => structuredClone(x);
const $ = id => document.getElementById(id);
const esc = x => String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const plural = (n,singular,multiple) => n===1?singular:multiple;
const size = n => n >= 1024 ? (n/1024).toLocaleString('pt-BR',{maximumFractionDigits:2})+' MiB' : n.toLocaleString('pt-BR',{maximumFractionDigits:1})+' KiB';
const itemName = id => {const i=ITEMS.find(i=>i.id===id);return i.name+' ('+i.year+')';};
const typeName = id => TYPES.find(t=>t[0]===id)[1];
let S, timer, returnFocus, dialogData;
function initial(){
  clearTimeout(timer);
  S={shell:'paginas',area:'simular',scenario:'normal',step:'draft',images:copy(FIXTURES),defaults:copy(DEFAULTS),cfg:copy(DEFAULTS),cfgDirty:false,auto:{...BASE,scope:'filmes',mode:'preview',storage:'guardar',types:{Primary:true,Thumb:true},batch:250,dirty:false},autoSaved:null,
    draft:{scope:'bibliotecas',libs:['filmes'],items:['viagem'],types:{Primary:true,Thumb:true},...BASE,custom:{},storage:'guardar',batch:250},analysis:null,selection:[],review:null,exec:null,serial:0,purge:[],search:'',editTypes:{},message:'',
    history:[{id:'h1',op:'op-exemplo-01',label:'Aplicação manual · exemplo A',item:'viagem',slot:'Capa principal',status:'available',original:486,fmt:'JPEG',dim:'1600 × 2400',age:40,active:true,policy:'Ajustes anteriores não registrados'},
      {id:'h2',op:'op-exemplo-02',label:'Aplicação agendada · exemplo B',item:'cidade',slot:'Fundo · posição 1',status:'available',original:1400,fmt:'JPEG',dim:'3840 × 2160',age:10,active:true,shared:true,policy:'Qualidade 85'},
      {id:'h3',op:'op-exemplo-02',label:'Aplicação agendada · exemplo B',item:'serie',slot:'Miniatura',status:'removed',original:220,fmt:'PNG',dim:'1280 × 720',age:10,active:true},
      {id:'h4',op:'op-exemplo-03',label:'Verificação incompleta · exemplo C',item:'cidade',slot:'Capa principal',status:'uncertain',original:96,fmt:'JPEG',dim:'900 × 900',age:50,active:true}]};
  S.autoSaved=copy(S.auto);
}
function route(){const m=location.hash.match(/^#\/p2\/(paginas|abas)\/(simular|executar|automacao|historico|configuracoes)$/);if(m){S.shell=m[1];S.area=m[2];}}
function go(area){if(S.area===area){render();return;}location.hash='#/p2/'+S.shell+'/'+area;}
function announce(t){$('announcer').textContent=t;}
function focus(id){$(id)?.focus();}
function invalidate(){if(S.analysis)S.analysis.stale=true;S.review=null;S.selection=[];S.message='Rascunho alterado. Faça uma nova simulação antes de aplicar.';}
function imagesChanged(){if(S.analysis)S.analysis.stale=true;S.review=null;S.selection=[];}
function hasScope(){const d=S.draft;return S.scenario!=='empty'&&(d.scope==='tudo'||(d.scope==='bibliotecas'?d.libs.length:d.items.length));}
function validManual(){const d=S.draft,enabled=Object.keys(d.types).filter(k=>d.types[k]);return hasScope()&&enabled.length>0&&enabled.every(k=>validPolicy(d.custom[k]||d))&&Number.isInteger(d.batch)&&d.batch>=1&&d.batch<=S.defaults.batch;}
function validPolicy(p){return (p.lossless||(Number.isInteger(p.quality)&&p.quality>=0&&p.quality<=100))&&p.ssim>=0&&p.ssim<=1&&Number.isInteger(p.dimension)&&p.dimension>=256&&p.dimension<=8192;}
function eligible(){return S.history.filter(h=>h.active&&h.status==='available');}
function expired(){return S.defaults.retention>0?eligible().filter(h=>h.age>=S.defaults.retention):[];}
function historyFor(row){return S.history.find(h=>h.active&&h.status==='available'&&h.item===row.item&&h.slot===row.slot);}
function expiryPlan(rows){const all=expired();const needed=new Set();for(const r of rows||[])if(r.action==='regenerate'){const h=historyFor(r);if(h)needed.add(h.id);}return{expired:all.filter(h=>!needed.has(h.id)),protected:all.filter(h=>needed.has(h.id))};}
function purgeIds(){const ok=new Set(eligible().map(h=>h.id));return S.purge.filter(id=>ok.has(id));}
function analyse(){
  if(!validManual())return;
  const d=copy(S.draft),rows=[];
  if(S.scenario!=='unavailable')for(const f of S.images){
    const item=ITEMS.find(i=>i.id===f.item);
    const included=d.scope==='tudo'||(d.scope==='itens'?d.items.includes(f.item):d.libs.includes(item.lib));
    if(!included||!d.types[f.type])continue;
    const p=d.custom[f.type]||d,r={...copy(f),policy:copy(p),action:'keep',proposed:false};
    if(f.state==='converted'){
      const previous=f.policy||BASE;
      const changed=Object.keys(BASE).some(k=>(k!=='dimension'||p.resize)&&previous[k]!==p[k]);
      if(changed&&!f.original)r.reason='Original indisponível. Não é possível regenerar nem recomprimir silenciosamente.';
      else if(changed){r.action='regenerate';r.proposed=true;r.reason='Original guardado íntegro. Qualidade proposta: '+(p.lossless?'sem perdas':p.quality)+'.';}
      else r.reason='Já utiliza estes ajustes. Nenhuma nova compressão.';
    }else if(f.state==='source'){r.action='convert';r.proposed=true;r.reason=f.type==='People'?'Foto global: também pode aparecer em outras bibliotecas.':'Imagem local elegível; filtros sintéticos aprovados.';}
    else if(f.state==='external')r.reason='WebP sem original do JellyP. Ajustes anteriores não registrados; não será recomprimido.';
    else if(f.state==='filter'){r.action='filtered';r.reason='Economia de 3%, abaixo do mínimo global de '+S.defaults.savings+'% (cenário fixo).';}
    else if(f.state==='shared'){r.action='filtered';r.reason='Referência compartilhada com outra biblioteca. Proteção global; inalterada.';}
    else{r.action='unavailable';r.reason='Referência remota. O JellyP não baixa imagens.';}
    rows.push(r);if(rows.length>=d.batch)break;
  }
  S.analysis={id:'sim-'+String(++S.serial).padStart(3,'0'),draft:d,rows,stale:false,failed:S.scenario==='unavailable'};
  S.selection=[];S.review=null;S.step='results';S.message='';render();focus('resultadoAnalise');
  if(S.analysis.failed)announce('Não foi possível analisar. A inspeção dos dados está indisponível e nenhuma imagem foi alterada.');
  else announce('Simulação concluída. '+rows.length+' '+plural(rows.length,'imagem avaliada','imagens avaliadas')+'. Nenhuma proposta selecionada.');
}
function totals(rows,storage){let reduction=0,originals=0,net=0;for(const r of rows){if(!r.proposed)continue;reduction+=r.source-r.output;if(storage==='guardar'){if(r.action==='convert')originals+=r.original;net+=r.action==='convert'?-r.output:r.source-r.output;}else net+=r.action==='regenerate'?r.source-r.output+r.original:r.source-r.output;}return{reduction,originals,net};}
function scopeText(d){return d.scope==='tudo'?'Todas as bibliotecas e metadata global':d.scope==='bibliotecas'?d.libs.map(x=>x==='filmes'?'Filmes':'Séries').join(' + '):d.items.map(itemName).join(', ')||'Nenhum item';}
function effective(p){if(!validPolicy(p))return 'Revise os ajustes incompletos ou fora dos limites';return(p.lossless?'Sem perdas':'Qualidade '+p.quality)+' · '+(p.resize?'até '+p.dimension+' px':'dimensões originais')+' · SSIM ≥ '+p.ssim.toLocaleString('pt-BR');}
function art(item){return '<div class="art '+(item==='cidade'?'city':'')+'" aria-hidden="true"><span>P2</span></div>';}
function heading(title,desc,id){return '<header class="area-head"><h1'+(id?' id="'+id+'" tabindex="-1"':'')+'>'+title+'</h1><p>'+desc+'</p></header>';}
function steps(step){return '<ol class="stepper" aria-label="Etapas do trabalho manual">'+['Selecionar','Simular e escolher','Revisar e aplicar'].map((t,i)=>'<li class="'+(i===step?'current':'')+'"'+(i===step?' aria-current="step"':'')+'><b>'+(i+1)+'</b>'+t+'</li>').join('')+'</ol>';}
function check(label,attr,checked,disabled=false){return '<label class="choice"><input type="checkbox" '+attr+(checked?' checked':'')+(disabled?' disabled':'')+'><span>'+label+'</span></label>';}
function num(label,attr,value,min,max,step=1){return '<label class="field"><span class="control-label">'+label+'</span><input type="number" '+attr+' value="'+value+'" min="'+min+'" max="'+max+'" step="'+step+'" required></label>';}
function select(label,attr,value,options){return '<label class="field"><span class="control-label">'+label+'</span><select '+attr+'>'+options.map(([v,t])=>'<option value="'+v+'"'+(value===v?' selected':'')+'>'+t+'</option>').join('')+'</select></label>';}
function icon(i){const paths=['<path d="M4 3h12v14H4zM7 7h6M7 10h6M7 13h3"/>','<path d="m7 3 10 7-10 7z"/>','<path d="M4 7a6 6 0 0 1 11-2l2 2M17 3v4h-4M16 13a6 6 0 0 1-11 2l-2-2M3 17v-4h4"/>','<path d="M4 4v5h5M4 9a7 7 0 1 1 0 5M10 6v5l3 2"/>','<path d="M3 5h14M3 10h14M3 15h14"/><circle cx="7" cy="5" r="2" fill="currentColor"/><circle cx="13" cy="10" r="2" fill="currentColor"/><circle cx="7" cy="15" r="2" fill="currentColor"/>'];return '<svg class="nav-icon" viewBox="0 0 20 20" fill="none" stroke="currentColor" stroke-width="1.4" aria-hidden="true">'+paths[i]+'</svg>';}
function render(move=false){
  const active=document.activeElement,key=active?.getAttribute('data-key'),detailFocus=active?.tagName==='SUMMARY'?active.parentElement.id:null,scroll=window.scrollY,details=[...document.querySelectorAll('main details[open]')].map(x=>x.id).filter(Boolean);
  document.body.dataset.shell=S.shell;$('shell').value=S.shell;$('scenario').value=S.scenario;
  $('shellhost').innerHTML=renderNav();
  const views={simular:viewSimular,executar:viewExecutar,automacao:viewAuto,historico:viewHistory,configuracoes:viewCfg};
  $('conteudo').innerHTML=S.shell==='abas'?'<div role="tabpanel" id="panel-'+S.area+'" aria-labelledby="tab-'+S.area+'">'+views[S.area]()+'</div>':views[S.area]();
  for(const id of details)if($(id))$(id).open=true;
  if(S.area==='historico'&&activeExec())$('conteudo').querySelectorAll('[data-act="restore"],[data-act="recover"],[data-act="purgeReview"]').forEach(n=>{n.disabled=true;});
  updateActivity();
  if(move){$('conteudo').focus();window.scrollTo(0,0);}else if(key){const next=[...document.querySelectorAll('[data-key]')].find(x=>x.getAttribute('data-key')===key);next?.focus({preventScroll:true});window.scrollTo(0,scroll);}else if(detailFocus){$(detailFocus)?.querySelector('summary')?.focus({preventScroll:true});window.scrollTo(0,scroll);}
}
function renderNav(){
  if(S.shell==='abas')return '<nav class="tabs" id="shellnav" role="tablist" aria-label="Áreas do JellyP">'+AREAS.map(([id,n])=>'<button role="tab" id="tab-'+id+'" data-act="tab" data-value="'+id+'" aria-selected="'+(S.area===id)+'" tabindex="'+(S.area===id?0:-1)+'" aria-controls="panel-'+id+'">'+n+'</button>').join('')+'</nav>';
  return '<aside class="sidebar" id="shellnav"><div class="nav-label">GERENCIAR IMAGENS</div><nav aria-label="Áreas do JellyP">'+AREAS.map(([id,n],i)=>(i===2?'<div class="nav-separator"></div>':'')+'<a href="#/p2/paginas/'+id+'"'+(S.area===id?' aria-current="page"':'')+'>'+icon(i)+n+'</a>').join('')+'</nav><label class="mobile-area"><span class="control-label">Área do JellyP</span><select id="areaMenu">'+AREAS.map(([id,n])=>'<option value="'+id+'"'+(id===S.area?' selected':'')+'>'+n+'</option>').join('')+'</select></label></aside>';
}
function updateActivity(){const e=S.exec;$('activity').innerHTML=e?'<a class="activity-link" href="#/p2/'+S.shell+'/executar">'+(['inventory','processing','waiting','cancelling'].includes(e.phase)?'<span class="dot"></span>Operação em andamento':'Última operação')+' · '+esc(e.id)+'</a>':'';}
function viewSimular(){return heading('Simular','Veja o que mudaria. Só as imagens que você escolher poderão seguir para aplicação.','simTitle')+(S.step==='results'&&S.analysis?viewResults():viewDraft());}
function viewDraft(){const d=S.draft,disabled=!validManual();let error='';if(!hasScope())error='Escolha pelo menos uma biblioteca ou item. Seleção vazia não significa tudo.';else if(!Object.values(d.types).some(Boolean))error='Marque pelo menos um tipo de imagem.';else if(!validManual())error='Revise os ajustes: qualidade 0–100, SSIM 0–1, dimensão 256–8192 e limite até '+S.defaults.batch+'.';
  return steps(0)+'<div class="work-grid"><div class="surface"><section class="form-section"><h2 class="section-label"><span class="section-num">01</span> Onde analisar</h2>'+select('Alcance','data-draft="scope" data-key="scope"',d.scope,[['bibliotecas','Bibliotecas selecionadas'],['itens','Itens específicos'],['tudo','Todas as bibliotecas e metadata global']])+viewScope(d)+'</section><section class="form-section"><h2 class="section-label"><span class="section-num">02</span> Imagens e qualidade</h2><span class="control-label">Tipos que serão avaliados</span>'+TYPES.slice(0,2).map(([id,n])=>typeRow(id,n,d,'manual')).join('')+'<details id="moreTypes"><summary>Outros tipos de imagem (fundo, logotipo, pessoas…)</summary>'+TYPES.slice(2).map(([id,n])=>typeRow(id,n,d,'manual')).join('')+'</details><div style="margin-top:18px"><label class="control-label" for="manual-quality">Qualidade do WebP · rascunho manual</label><div class="quality-line"><input id="manual-quality" aria-label="Qualidade do WebP" type="number" min="0" max="100" data-draft="quality" data-key="quality" value="'+d.quality+'"'+(d.lossless?' disabled':'')+'><p>85 é um ponto de partida.<br>Não é uma porcentagem de fidelidade.</p></div></div><details id="manualAdvanced"><summary>Codificação, dimensões e limite de teste</summary>'+policyExtra(d,'data-draft')+num('Limite deste teste (máximo '+S.defaults.batch+')','data-draft="batch" data-key="batch"',d.batch,1,S.defaults.batch)+'<p class="help">A economia mínima é global: '+S.defaults.savings+'% e '+S.defaults.kib+' KiB. Transparência e integridade continuam protegidas.</p></details></section><section class="form-section"><h2 class="section-label"><span class="section-num">03</span> Originais após aplicar</h2>'+storage(d.storage,'data-draft="storage"')+'</section></div><aside class="surface summary-panel" aria-label="Resumo do rascunho"><h2>Seu teste manual</h2><div class="summary-line"><small>ALCANCE</small><p>'+esc(hasScope()?scopeText(d):'Nenhuma seleção')+'</p></div><div class="summary-line"><small>IMAGENS</small><p>'+Object.keys(d.types).filter(k=>d.types[k]).map(typeName).join(' · ')+'</p></div><div class="summary-line"><small>AJUSTES DO RASCUNHO</small><p>'+effective(d)+'</p></div><div class="summary-line"><small>ORIGINAIS</small><p>'+(d.storage==='guardar'?'Guardar para poder desfazer':'Remover após verificar')+'</p><p class="help">O impacto de espaço aparece na simulação.</p></div>'+(error?'<p class="error-message" role="status">'+error+'</p>':'')+'<button class="primary" data-act="analyse"'+(disabled?' disabled':'')+'>Simular as imagens</button><div class="isolation"><span aria-hidden="true">✓</span><span>Simular não altera imagens,<br>padrões ou automação.</span></div>'+(S.analysis?'<button class="quiet" data-act="showResults">Consultar simulação anterior</button>':'')+'<button class="quiet" data-act="defaults">Usar padrões salvos</button></aside></div>';
}
function viewScope(d){if(S.scenario==='empty')return '<div class="notice warn">Nenhuma biblioteca disponível neste cenário. Nada será analisado.</div>';if(d.scope==='bibliotecas')return '<div class="library-list">'+[['filmes','Filmes','2 itens de exemplo'],['series','Séries','1 item de exemplo']].map(([id,n,c])=>'<label class="library"><input data-key="lib-'+id+'" type="checkbox" data-lib="'+id+'"'+(d.libs.includes(id)?' checked':'')+'><span><strong>'+n+'</strong><small>'+c+'</small></span></label>').join('')+'</div><p class="help">Inclui imagens da biblioteca e descendentes. Imagens ao lado da mídia continuam excluídas.</p>';
  if(d.scope==='tudo')return '<div class="notice warn">Alcance amplo e explícito: todas as bibliotecas e metadata global. O limite deste teste continua valendo.</div>';
  return '<label class="field"><span class="control-label">Encontrar um item de exemplo</span><input type="search" data-search data-key="search" value="'+esc(S.search)+'" placeholder="Nome, ano ou tipo"></label><div id="itemChoices">'+itemChoices()+'</div><p class="help">Um item seleciona só suas próprias imagens, não os episódios de uma série. “Ensaio sem imagens” não tem imagens cadastradas.</p>'+(S.scenario==='unavailable'?'<div class="notice warn">Inspeção indisponível. Uma tentativa de simulação apresentará o erro, não um sucesso vazio.</div>':'');
}
function itemChoices(){const matches=ITEMS.filter(i=>(i.name+' '+i.year+' '+i.kind).toLocaleLowerCase().includes(S.search.toLocaleLowerCase()));return matches.length?matches.map(i=>check(esc(i.name)+' <small>'+i.year+' · '+i.kind+' · '+(i.id==='sem'?'sem imagens próprias':i.id==='viagem'?'capa, miniatura e logotipo':'imagens locais de exemplo')+'</small>','data-item="'+i.id+'" data-key="item-'+i.id+'"',S.draft.items.includes(i.id))).join(''):'<p class="help">Nenhum item encontrado. A seleção anterior foi preservada.</p>';}
function policyExtra(p,attr){return check('Sem perdas (qualidade numérica não se aplica)',attr+'="lossless" data-key="'+attr+'-lossless"',p.lossless)+check('Permitir redução de dimensões',attr+'="resize" data-key="'+attr+'-resize"',p.resize)+'<div class="form-cols">'+num('Maior lado (px)',attr+'="dimension" data-key="'+attr+'-dimension"',p.dimension,256,8192)+num('Semelhança mínima (SSIM)',attr+'="ssim" data-key="'+attr+'-ssim"',p.ssim,0,1,0.01)+'</div><p class="help">Sem redução, preserva as dimensões originais. 100 com perdas não equivale a sem perdas.</p>';}
function typeRow(id,n,d,owner){
  const custom=d.custom[id],p=custom||d,enabled=!!d.types?.[id]||owner==='cfg',edit=S.editTypes[owner+id];
  const origin=custom?'Personalizado':owner==='manual'?'Do rascunho':'Usa padrões';
  const identity=owner==='cfg'
    ?'<div><strong>'+n+'</strong><p class="help">'+effective(p)+'</p></div>'
    :check('<strong>'+n+'</strong><small>'+effective(p)+'</small>','data-type="'+id+'" data-key="type-'+id+'"',enabled);
  let editor='';
  if(edit){
    editor='<div class="type-editor">'+check('Personalizar política completa','data-custom="'+id+'" data-owner="'+owner+'" data-key="custom-'+owner+id+'"',!!custom);
    if(custom){
      const attr=key=>'data-policy="'+key+'" data-owner="'+owner+'" data-id="'+id+'" data-key="'+owner+id+'-'+key+'"';
      editor+=num('Qualidade',attr('quality'),custom.quality,0,100);
      editor+=check('Sem perdas',attr('lossless'),custom.lossless)+check('Permitir redução',attr('resize'),custom.resize);
      editor+=num('Maior lado (px)',attr('dimension'),custom.dimension,256,8192)+num('SSIM mínimo',attr('ssim'),custom.ssim,0,1,0.01);
    }
    editor+='<p class="help">Personalizado substitui todos os ajustes deste tipo. Economia, reserva, quota e retenção continuam globais.</p></div>';
  }
  return '<div class="type-row">'+identity+'<button class="quiet" data-act="editType" data-owner="'+owner+'" data-id="'+id+'" data-key="edit-'+owner+id+'" aria-expanded="'+!!edit+'">'+origin+'</button>'+editor+'</div>';
}
function storage(value,attr){return '<div class="choice-stack">'+[['guardar','Guardar originais','Permite restaurar e gerar novamente depois. Pode ocupar mais espaço inicialmente.'],['remover','Remover após verificar','Libera espaço, mas encerra restauração e regeneração destas imagens.']].map(([v,n,t])=>'<label class="choice"><input type="radio" '+attr+' data-key="'+attr.replaceAll('"','')+'-'+v+'" name="'+attr.replaceAll('"','')+'" value="'+v+'"'+(value===v?' checked':'')+'><span>'+n+'<small>'+t+'</small></span></label>').join('')+'</div>';}
function actionTitle(r){return r.action==='regenerate'?'Gerar novamente a partir do original':r.action==='convert'?'Converter para WebP':r.action==='unavailable'?'Indisponível':r.action==='filtered'?'Manter · filtro de proteção':'Manter imagem atual';}
function imageRow(r,selectable=true){
  let selection='';
  if(selectable)selection=r.proposed
    ?'<label class="row-check"><input type="checkbox" data-row="'+r.id+'" data-key="row-'+r.id+'" aria-label="Selecionar '+esc(itemName(r.item)+' · '+r.slot)+'"'+(S.selection.includes(r.id)?' checked':'')+(S.analysis.stale?' disabled':'')+'></label>'
    :'<div class="row-check"><span class="muted" aria-label="Não proposta">—</span></div>';
  return '<div class="image-row" data-image-id="'+r.id+'">'+selection+art(r.item)+'<div><strong>'+esc(itemName(r.item))+'</strong><p class="help">'+esc(r.slot)+'<br>'+r.fmt+' · '+r.dim+' · '+size(r.source)+'</p><details><summary>Identidade e ajustes</summary><p class="help">Slot sintético: '+r.id+'<br>'+effective(r.policy)+'</p></details></div><div class="action-cell"><span class="action-tag '+(!r.proposed?'keep':'')+'">'+(r.action==='regenerate'?'REGENERAR':r.action==='convert'?'CONVERTER':r.action==='unavailable'?'INDISPONÍVEL':'MANTER')+'</span><div class="outcome">'+actionTitle(r)+'</div><p class="help">'+esc(r.reason)+'</p>'+(r.proposed?'<p class="help">Saída proposta: WebP · '+(r.policy.resize?'até '+r.policy.dimension+' px':r.dim)+' · ~'+size(r.output)+'<br>'+(S.analysis.draft.storage==='guardar'?'Original disponível após aplicar.':'Sem restauração após remover o original.')+'</p>':'')+'</div></div>';
}
function metricView(t){return '<div class="metrics" aria-label="Estimativas deste conjunto"><div class="metric"><small>Redução nas imagens</small><b>~'+size(t.reduction)+'</b><p class="help">Não é espaço livre.</p></div><div class="metric"><small>Novos originais a guardar</small><b>'+size(t.originals)+'</b><p class="help">Regeneração reutiliza o original.</p></div><div class="metric"><small>Impacto líquido estimado</small><b>'+size(Math.abs(t.net))+'</b><p class="help">'+(t.net<0?'a mais em uso':'liberados neste conjunto')+'</p></div></div>';}
function viewResults(){const a=S.analysis,rows=a.rows,proposed=rows.filter(r=>r.proposed);return steps(1)+'<div class="snapshot"><div><p><strong>'+esc(scopeText(a.draft))+'</strong> · '+effective(a.draft)+'</p><small>'+a.id+' · ajustes congelados · nada foi alterado</small></div><button data-act="editDraft">Editar seleção</button></div>'+(a.stale?'<div class="notice warn" role="status">Esta simulação está desatualizada. O relatório foi preservado, mas não pode mais autorizar alterações. <button data-act="editDraft">Revisar rascunho</button></div>':'')+(a.failed?'<section class="surface empty"><h2 id="resultadoAnalise" tabindex="-1">Não foi possível analisar</h2><p>A inspeção dos dados está indisponível. Nenhuma imagem foi alterada. Isso não significa que todas já estão otimizadas.</p><button data-act="analyse">Tentar novamente</button></section>':rows.length?'<section class="surface"><div class="result-head"><div><span class="eyebrow">RESULTADO DA SIMULAÇÃO</span><h2 id="resultadoAnalise" tabindex="-1">Escolha o que aplicar</h2></div><button class="quiet" data-act="allRows"'+(a.stale||!proposed.length?' disabled':'')+'>Selecionar propostas ('+proposed.length+')</button></div><div class="counts"><span><b>'+rows.length+'</b> '+plural(rows.length,'avaliada','avaliadas')+'</span><span><b>'+proposed.length+'</b> '+plural(proposed.length,'proposta','propostas')+'</span><span><b>'+rows.filter(r=>r.action==='keep').length+'</b> '+plural(rows.filter(r=>r.action==='keep').length,'mantida','mantidas')+'</span><span><b>'+rows.filter(r=>r.action==='filtered').length+'</b> por filtro</span><span><b>'+rows.filter(r=>r.action==='unavailable').length+'</b> '+plural(rows.filter(r=>r.action==='unavailable').length,'indisponível','indisponíveis')+'</span><span>0 '+plural(0,'falha','falhas')+'</span></div><div class="result-list">'+rows.map(r=>imageRow(r)).join('')+'</div>'+(!proposed.length?'<p class="notice">Nenhuma alteração proposta. Consulte os motivos de cada imagem acima.</p>':'')+'<p class="help">Estimativa '+(proposed.length===1?'da proposta':'das '+proposed.length+' propostas')+', não dos totais do plugin:</p>'+metricView(totals(proposed,a.draft.storage))+'</section>':'<section class="surface empty"><h2 id="resultadoAnalise" tabindex="-1">Nenhuma imagem dos tipos escolhidos</h2><p>Os itens selecionados não têm imagens próprias desses tipos. O JellyP não baixa imagens ausentes.</p><button data-act="editDraft">Alterar seleção</button></section>')+'<div class="selection-bar"><div><p><strong>'+S.selection.length+' '+plural(S.selection.length,'imagem selecionada','imagens selecionadas')+'</strong></p><small>Somente '+plural(S.selection.length,'esta identidade seguirá','estas identidades seguirão')+' para revisão.</small></div><button class="primary" data-act="review"'+(!S.selection.length||a.stale?' disabled':'')+'>Revisar '+S.selection.length+' '+plural(S.selection.length,'imagem','imagens')+' <span aria-hidden="true">→</span></button></div>';}
function createReview(){if(!S.analysis||S.analysis.stale||!S.selection.length)return;if(activeExec()){go('executar');return;}const rows=copy(S.analysis.rows.filter(r=>r.proposed&&S.selection.includes(r.id))),plan=expiryPlan(rows);S.exec=null;S.review={analysisId:S.analysis.id,draft:copy(S.analysis.draft),rows,expired:copy(plan.expired),protectedExpiry:copy(plan.protected),ack:false,permanent:false,expiryAck:false};go('executar');}
function canApply(){const r=S.review;return r&&r.rows.length&&r.ack&&(r.draft.storage!=='remover'||r.permanent)&&(!r.expired.length||r.expiryAck)&&!['conflict','recovery'].includes(S.scenario)&&!S.analysis?.stale&&!activeExec();}
function activeExec(){return S.exec&&['inventory','processing','waiting','cancelling'].includes(S.exec.phase);}
function viewExecutar(){let out=heading('Executar','Revise o conjunto exato. A aplicação revalida cada imagem e não inclui substitutas.','execTitle');
  if(S.scenario==='recovery')out+='<div class="notice bad" role="alert"><strong>Recuperação necessária.</strong> Uma transação de exemplo bloqueia novas aplicações. <button data-act="go" data-value="historico">Examinar no histórico</button></div>';
  if(S.scenario==='conflict')out+='<div class="notice warn" role="status">Outra operação JellyP está ativa ou na fila. Sua seleção está preservada; aguarde antes de aplicar.</div>';
  if(S.exec)return out+'<div id="executionBody">'+executionBody()+'</div>';
  const r=S.review;if(!r)return out+'<section class="surface empty"><h2>Nenhuma seleção aguardando aplicação</h2><p>Comece com uma simulação e escolha as imagens. Navegar até aqui não autoriza nada.</p><button class="primary" data-act="go" data-value="simular">Ir para Simular</button></section>';
  const regen=r.rows.filter(x=>x.action==='regenerate').length;
  const imageCount=r.rows.length+' '+(r.rows.length===1?'imagem':'imagens');
  out+=steps(2)+'<div class="work-grid"><section class="surface"><h2>Revisão final · '+imageCount+'</h2><p class="operation-id">'+r.analysisId+' · origem manual</p><div class="key-values"><div><small>Alcance analisado</small><p>'+esc(scopeText(r.draft))+'</p></div><div><small>Ações autorizadas</small><p>'+regen+' regenerar · '+(r.rows.length-regen)+' converter</p></div></div><div class="review-list">'+r.rows.map(x=>imageRow(x,false)).join('')+'</div><p class="help">Cada linha mostra seus ajustes efetivos. Fontes, originais, referências, espaço e conflitos serão verificados outra vez. Uma imagem inválida não será substituída por outra.</p><button class="quiet" data-act="backResults">← Alterar imagens selecionadas</button></section><aside class="surface summary-panel"><h2>Antes de autorizar</h2><p>'+(r.draft.storage==='guardar'?'Os originais serão guardados. Você poderá restaurar as imagens depois.':'Os originais serão removidos após verificação. Você não poderá restaurar nem regenerar estas imagens.')+'</p>'+metricView(totals(r.rows,r.draft.storage))+'<p class="help">Reserva global: '+S.defaults.reserve+' GiB · orçamento: '+S.defaults.quota+' MiB.</p>'+(r.expired.length?'<div class="notice warn"><strong>Expiração global</strong><p>'+r.expired.length+' '+plural(r.expired.length,'original','originais')+' · '+size(r.expired.reduce((n,h)=>n+h.original,0))+' '+(r.expired.length===1?'será removido':'serão removidos')+' pela retenção de '+S.defaults.retention+' dias, inclusive fora da seleção manual.</p>'+r.expired.map(h=>'<p class="help">'+esc(itemName(h.item))+' · '+h.slot+'</p>').join('')+'</div>':'<p class="help">Retenção global: '+(S.defaults.retention?'nenhum original elegível para expirar agora.':'guardar até remoção explícita. Nenhuma expiração automática.')+'</p>')+(r.protectedExpiry?.length?'<p class="help">Proteção desta operação: '+r.protectedExpiry.length+' '+plural(r.protectedExpiry.length,'original necessário à regeneração selecionada','originais necessários à regeneração selecionada')+' '+(r.protectedExpiry.length===1?'não será removido':'não serão removidos')+' pela expiração global. '+r.protectedExpiry.map(h=>esc(itemName(h.item))+' · '+h.slot).join('; ')+'</p>':'')+'<div class="ack">'+check((r.rows.length===1?'Revisei esta ':'Revisei estas ')+imageCount+' e seus ajustes.','data-ack="ack" data-key="ack"',r.ack)+(r.draft.storage==='remover'?check('Autorizo a remoção permanente dos originais destas imagens.','data-ack="permanent" data-key="permanent"',r.permanent):'')+(r.expired.length?check('Autorizo também a expiração global listada acima.','data-ack="expiryAck" data-key="expiryAck"',r.expiryAck):'')+'</div><button class="primary" data-act="apply"'+(!canApply()?' disabled':'')+'>Aplicar '+(r.rows.length===1?'à ':'às ')+imageCount+'</button><p class="help">Nesta bancada, aplicar apenas encena a operação.</p></aside></div>';return out;
}
function startExecution(){if(!canApply())return;const r=S.review;S.exec={id:'exec-'+String(++S.serial).padStart(3,'0'),phase:['waiting','waitNext'].includes(S.scenario)?'waiting':'inventory',rows:copy(r.rows),draft:copy(r.draft),expired:copy(r.expired),retired:[],results:[],cancel:false};S.review=null;imagesChanged();render();focus('andamento');announce('Operação sintética iniciada.');schedule();}
function schedule(){clearTimeout(timer);if(!activeExec()||S.exec.phase==='waiting')return;timer=setTimeout(advance,850);}
function advance(){const e=S.exec;if(!e||!activeExec()||e.phase==='waiting')return;
  if(e.phase==='inventory'){e.phase='processing';for(const h of e.expired){const current=S.history.find(x=>x.id===h.id);if(current?.status==='available'&&current.active){current.status='removed';e.retired.push(copy(current));removeImageOriginal(current);}}updateExecution();schedule();return;}
  const r=e.rows[e.results.length];if(r){const image=S.images.find(f=>f.id===r.id);const failed=(S.scenario==='changed'&&e.results.length===0)||!image||image.fmt!==r.fmt||image.source!==r.source||image.dim!==r.dim||(r.action==='regenerate'&&(!image.original||image.original!==r.original));e.results.push({...r,result:failed?'invalid':'done'});if(!failed){
    for(const h of S.history)if(h.item===r.item&&h.slot===r.slot)h.active=false;
    S.history.unshift({id:e.id+'-'+r.id,op:e.id,label:'Aplicação manual · '+e.id,imageId:r.id,item:r.item,slot:r.slot,status:e.draft.storage==='guardar'?'available':'removed',original:r.original,fmt:r.action==='regenerate'?'JPEG':r.fmt,dim:r.dim,age:0,active:true,policy:effective(r.policy)});
    const image=S.images.find(f=>f.id===r.id);Object.assign(image,{state:'converted',fmt:'WebP',source:r.output,policy:copy(r.policy),original:e.draft.storage==='guardar'?r.original:0});
  }}
  if(e.cancel)e.phase='cancelled';else if(e.results.length===e.rows.length)e.phase='done';updateExecution();if(e.phase==='done'||e.phase==='cancelled'){const done=e.results.filter(x=>x.result==='done').length;announce('Operação '+(e.phase==='done'?'concluída':'interrompida')+'. '+done+' '+plural(done,'aplicada','aplicadas')+'.');}else schedule();
}
function updateExecution(){if(S.area==='executar'&&$('executionBody')){const active=document.activeElement,wasInside=$('executionBody').contains(active),act=active?.dataset.act,id=active?.id;$('executionBody').innerHTML=executionBody();if(wasInside){const next=id?$(id):$('executionBody').querySelector('[data-act="'+act+'"]'),target=next&&!next.disabled?next:$('andamento');target?.focus({preventScroll:true});}}else if(S.area==='historico'&&!activeExec())render();updateActivity();}
function removeImageOriginal(h){const image=S.images.find(f=>f.item===h.item&&f.slot===h.slot);if(image)image.original=0;}
function cancelExecution(){if(!activeExec())return;if(S.exec.phase==='waiting'||S.exec.phase==='inventory'){clearTimeout(timer);S.exec.phase='cancelled';updateExecution();announce('Espera interrompida. Nenhuma imagem foi iniciada.');}else{S.exec.cancel=true;S.exec.phase='cancelling';updateExecution();schedule();announce('Parada solicitada. A transação atual deve terminar com segurança.');}}
function executionBody(){
  const content=operationView(),retired=S.exec.retired||[];
  return content+(retired.length?'<section class="surface"><h2>Expiração global desta operação</h2><p>'+retired.length+' '+plural(retired.length,'original removido','originais removidos')+' · '+size(retired.reduce((n,h)=>n+h.original,0))+'</p><p class="help">Conjunto separado das imagens aplicadas, autorizado na revisão.</p><ul>'+retired.map(h=>'<li>'+esc(itemName(h.item))+' · '+h.slot+'</li>').join('')+'</ul></section>':'');
}
function operationView(){const e=S.exec,done=e.results.filter(x=>x.result==='done').length,invalid=e.results.filter(x=>x.result==='invalid').length,failed=e.results.filter(x=>x.result==='failed').length,skipped=e.results.filter(x=>x.result==='skipped').length,notStarted=Math.max(0,e.rows.length-e.results.length),active=activeExec();let title,desc;
  if(e.phase==='inventory'){title='Verificando referências compartilhadas';desc='Leitura global do servidor, sem autorizar conversão global. O total de itens ainda é desconhecido.';}
  else if(e.phase==='waiting'){title='Aguardando metadata';desc='Uma varredura da biblioteca impede a aplicação. A operação continuará sozinha quando terminar. Simulações não precisam esperar.';}
  else if(e.phase==='processing'||e.phase==='cancelling'){title=e.phase==='cancelling'?'Parada solicitada':'Aplicando às imagens selecionadas';desc=e.phase==='cancelling'?'A imagem atual termina com segurança; nenhuma outra será iniciada.':e.results.length+' de '+e.rows.length+' '+plural(e.rows.length,'imagem processada','imagens processadas')+'. Fontes e referências são revalidadas.';}
  else {title=e.phase==='cancelled'?'Operação interrompida':failed||invalid?'Concluída com pendências':'Aplicação concluída';desc=e.phase==='cancelled'?'O restante não foi iniciado. Continuar exige uma nova seleção revisada.':'Consulte o resultado por imagem. O relatório pertence a esta operação.';}
  return '<section class="surface"><div class="progress-heading"><span class="operation-id">'+e.id+' · manual · '+esc(scopeText(e.draft))+'</span><span class="badge">'+(active?'Em andamento':'Encerrada')+'</span></div><h2 id="andamento" tabindex="-1">'+title+'</h2><p class="muted">'+desc+'</p>'+(active?'<progress aria-label="Progresso das imagens"'+(['processing','cancelling'].includes(e.phase)?' max="'+e.rows.length+'" value="'+e.results.length+'"':'')+'></progress>':'')+'<div class="counts"><span><b>'+done+'</b> '+plural(done,'aplicada','aplicadas')+'</span><span><b>'+invalid+'</b> '+plural(invalid,'invalidada','invalidadas')+'</span><span><b>'+skipped+'</b> '+plural(skipped,'ignorada','ignoradas')+'</span><span><b>'+failed+'</b> '+plural(failed,'falha','falhas')+'</span><span><b>'+notStarted+'</b> '+plural(notStarted,'não iniciada','não iniciadas')+'</span></div>'+(e.results.length?'<ul class="execution-result">'+e.results.map(r=>'<li><span class="'+(r.result==='done'?'ok':r.result==='failed'?'bad':'warn')+'">'+(r.result==='done'?'✓ Aplicada':r.result==='invalid'?'Não aplicada · fonte alterada':r.result==='failed'?'Falha · persistência não concluída':'Ignorada · SSIM abaixo do mínimo')+'</span> — '+esc(itemName(r.item))+' · '+r.slot+'<small>'+(r.result==='done'?(e.draft.storage==='guardar'?'Original guardado; restauração disponível.':'Original removido após verificação.'):r.result==='failed'?'Cenário sintético; examine a recuperação antes de nova aplicação.':'Nenhuma imagem substituta foi incluída.')+'</small></li>').join('')+'</ul>':'')+(active?'<button data-act="cancel"'+(e.phase==='cancelling'?' disabled':'')+'>'+(e.phase==='waiting'?'Interromper a espera':'Parar após a imagem atual')+'</button><p class="help">Você pode navegar. A operação continua nesta sessão do protótipo; recarregar a descarta.</p>':metricView(totals(e.results.filter(r=>r.result==='done'),e.draft.storage))+'<div class="btn-row"><button class="primary" data-act="go" data-value="historico">Ver histórico e restaurar</button><button data-act="newRun">Nova simulação</button></div>')+'</section>';
}
function viewAuto(){const a=S.auto;return heading('Automação','Trabalho futuro tem configuração própria. Seu teste manual não é salvo aqui.','autoTitle')+'<div class="work-grid"><section class="surface"><h2>Configuração das tarefas</h2>'+select('Biblioteca da automação','data-auto="scope" data-key="auto-scope"',a.scope,[['filmes','Filmes'],['series','Séries']])+select('As tarefas podem','data-auto="mode" data-key="auto-mode"',a.mode,[['preview','Somente simular'],['apply','Aplicar alterações']])+'<div class="form-cols">'+num('Qualidade própria','data-auto="quality" data-key="auto-quality"',a.quality,0,100)+num('Limite por execução','data-auto="batch" data-key="auto-batch"',a.batch,1,S.defaults.batch)+'</div><h3>Tipos de imagem</h3>'+TYPES.map(([id,n])=>check(n,'data-auto-type="'+id+'" data-key="auto-type-'+id+'"',a.types[id])).join('')+'<h3 style="margin-top:22px">Originais da automação</h3>'+storage(a.storage,'data-auto="storage"')+(a.mode==='apply'&&a.storage==='remover'?'<div class="notice warn">Salvar exige autorização própria para remover originais em execuções futuras.</div>':'')+'<div class="btn-row" style="margin-top:22px"><button class="primary" data-act="saveAuto"'+(!a.dirty||!Number.isInteger(a.quality)||a.quality<0||a.quality>100||!Number.isInteger(a.batch)||a.batch<1||a.batch>S.defaults.batch||!Object.values(a.types).some(Boolean)?' disabled':'')+'>Salvar configuração da automação</button></div><p class="help" role="status" id="autoStatus">'+(a.dirty?'Alterações não salvas.':(S.message==='auto'?'Automação salva nesta sessão. O rascunho manual não mudou. ':'Configuração salva de exemplo. ')+'Estado salvo: '+(S.autoSaved.mode==='preview'?'somente simular':'aplicação permitida')+'.')+'</p></section><aside class="surface"><h2>Estado salvo</h2><p><span class="badge">'+(S.autoSaved.mode==='preview'?'Somente simular':'Aplicação permitida')+'</span></p><p>'+(S.autoSaved.scope==='filmes'?'Filmes':'Séries')+' · qualidade '+S.autoSaved.quality+'<br>'+(S.autoSaved.storage==='guardar'?'Guardar originais':'Remover após verificar')+'</p><p class="help">Padrões e rascunho manual não são herdados ao salvar. Os limites de espaço e a retenção continuam globais.</p></aside></div><section class="surface"><h2>Tarefas nativas do Jellyfin</h2>'+(S.scenario==='tasks'?'<div class="notice warn">Dados de tarefas indisponíveis. Não é possível concluir que estejam desativadas ou sem horário.</div>':'<div class="task-row"><div><strong>Otimizar imagens das bibliotecas</strong><small>Nenhum horário configurado</small></div><span class="badge">Ociosa</span></div><div class="task-row"><div><strong>Sincronizar ajustes das imagens</strong><small>Exemplo: domingo às 04:00 · 1 disparo nativo</small></div><span class="badge">Ociosa</span></div>')+'<p class="help">Ociosa não significa desativada. Sem horário não significa aplicação proibida. Os disparos são administrados no Jellyfin, não por um segundo agendador.</p><details><summary>Integração proposta</summary><p class="help">Chaves preservadas: JellyPOptimizeArtwork e JellyPSynchronizePolicies. O link real às tarefas será validado no host em P5; não há navegação a servidor neste protótipo.</p></details></section>';}
const statusText=h=>!h.active?'Transação anterior · não ativa':({available:'Original disponível',removed:'Original removido',restored:'Original restaurado',uncertain:'Original incerto · preservado'}[h.status]);
function viewHistory(){const selectedPurge=purgeIds();let out=heading('Histórico e originais','Veja o que aconteceu e quais alterações ainda podem ser desfeitas.','historyTitle');
  if(activeExec())out+='<div class="notice warn" role="status">Há uma operação em andamento. Consulte os registros, mas aguarde sua conclusão antes de restaurar ou remover originais. <button data-act="go" data-value="executar">Acompanhar operação</button></div>';
  if(S.scenario==='recovery')out+='<div class="notice bad"><strong>1 transação requer recuperação.</strong> Novas aplicações estão bloqueadas. Este cenário usa um original de exemplo.<p><button data-act="recover">Revisar restauração de recuperação</button></p></div>';
  if(S.message==='restored')out+='<div class="notice" role="status">Original restaurado no cenário. Formato, dimensões, bytes e referência foram verificados de forma simulada; nenhuma evidência real foi produzida.</div>';
  if(S.message==='purged')out+='<div class="notice" role="status">Remoção sintética concluída somente para os originais revisados que continuavam elegíveis. Os incertos foram preservados.</div>';
  out+='<section class="surface"><h2>Operações</h2>';for(const op of [...new Set(S.history.map(h=>h.op))]){const hs=S.history.filter(h=>h.op===op);out+='<article class="history-group"><header><div><h3>'+esc(hs[0].label)+'</h3><span class="operation-id">'+op+'</span></div><span class="badge">'+hs.length+' '+plural(hs.length,'imagem','imagens')+'</span></header>'+hs.map(h=>'<div class="history-record" data-record="'+h.id+'">'+art(h.item)+'<div><strong>'+esc(itemName(h.item))+'</strong><p class="help">'+h.slot+' · <span class="'+(h.active&&h.status==='available'?'ok':h.status==='uncertain'?'warn':'')+'">'+statusText(h)+'</span></p><details id="evidence-'+h.id+'"><summary>Arquivo e evidência de '+(h.status==='restored'?'restauração':'origem')+'</summary><div class="evidence"><p>'+(h.status==='restored'?'Armazenado após restaurar':'Original de origem')+': <strong>'+h.fmt+' · '+h.dim+' · '+size(h.original)+'</strong></p><p>'+esc(h.policy||'Ajustes anteriores não registrados')+'</p><p>'+(h.status==='uncertain'?'Integridade não verificada. Remoção bloqueada.':h.status==='removed'?'Original não está disponível. Restauração e regeneração indisponíveis.':'Hash e referência '+(h.status==='restored'?'correspondem ao original':'íntegros')+' (evidência sintética).')+'</p><p>O navegador pode receber WebP mesmo após restaurar um JPEG ou PNG. A resposta HTTP não comprova o formato armazenado.</p><span class="operation-id">Transação '+h.id+' · '+(h.active?'ativa':'anterior, somente consulta')+'</span></div></details></div>'+(h.status==='available'&&h.active?'<button data-act="restore" data-id="'+h.id+'">Restaurar original</button>':'')+'</div>').join('')+'</article>';}
  out+='</section><section class="surface"><h2>Remover originais guardados</h2><p class="muted">Uma decisão permanente, separada da aplicação de imagens.</p>'+(eligible().length?eligible().map(h=>'<label class="purge-row"><input type="checkbox" data-purge="'+h.id+'" data-key="purge-'+h.id+'"'+(selectedPurge.includes(h.id)?' checked':'')+'><span>'+esc(itemName(h.item))+'<small>'+h.slot+'</small></span><span class="size">'+size(h.original)+'</span></label>').join(''):'<p class="notice">Nenhum original elegível guardado.</p>')+S.history.filter(h=>h.status==='uncertain'&&h.active).map(h=>'<div class="purge-row"><span class="warn">—</span><span>'+esc(itemName(h.item))+'<small>Incerto: não foi possível verificar. Será preservado.</small></span></div>').join('')+'<div class="btn-row" style="margin-top:20px"><button data-act="purgeReview"'+(!selectedPurge.length?' disabled':'')+'>Revisar remoção ('+selectedPurge.length+')</button><button class="quiet" data-act="purgeAll"'+(!eligible().length?' disabled':'')+'>Selecionar todos os elegíveis do plugin</button></div><p class="help">Selecionar todos apenas marca os originais; não remove nada. A revisão lista o alcance e os bytes exatos.</p></section><details id="pluginTotals"><summary>Totais do plugin · exemplo separado das simulações</summary><p class="help">Originais guardados: '+size(S.history.filter(h=>h.active&&['available','uncertain'].includes(h.status)).reduce((n,h)=>n+h.original,0))+'. Espaço líquido total: não calculado nesta fixture. Não inclui cache, logs ou custo do sistema de arquivos.</p></details>';return out;}
function viewCfg(){const c=S.cfg;return heading('Configurações','Padrões para novos rascunhos e limites globais. Nada é salvo automaticamente.','cfgTitle')+'<div class="work-grid"><div><section class="surface"><h2>Padrões de codificação</h2>'+num('Qualidade padrão','data-cfg="quality" data-key="cfg-quality"',c.quality,0,100)+policyExtra(c,'data-cfg')+'<details id="cfgTypes"><summary>Padrões por tipo · substituição completa</summary>'+TYPES.map(([id,n])=>typeRow(id,n,c,'cfg')).join('')+'</details></section><section class="surface"><h2>Limites globais</h2><p class="help">Valem para aplicação manual e automação. Um rascunho não os altera.</p><div class="form-cols" style="margin-top:18px">'+num('Imagens por execução','data-cfg="batch" data-key="cfg-batch"',c.batch,1,10000)+num('Reserva livre (GiB)','data-cfg="reserve" data-key="cfg-reserve"',c.reserve,0.0625,10000,0.0625)+num('Orçamento de originais (MiB)','data-cfg="quota" data-key="cfg-quota"',c.quota,32,100000)+num('Economia mínima (%)','data-cfg="savings" data-key="cfg-savings"',c.savings,0,90)+num('Economia mínima (KiB)','data-cfg="kib" data-key="cfg-kib"',c.kib,0,100000)+num('Retenção de originais (dias)','data-cfg="retention" data-key="cfg-retention"',c.retention,0,3650)+'</div><p class="help">0 guarda até remoção explícita. Um valor maior expira os originais elegíveis no início de uma aplicação, inclusive fora de sua seleção. A revisão deve mostrar quantidade e bytes e pedir autorização.</p></section></div><aside class="surface summary-panel"><h2>Padrões salvos</h2><p>'+effective(S.defaults)+'</p><p class="help">Salvar aqui não sobrescreve o rascunho manual nem a configuração da automação. Em Simular, “Usar padrões salvos” faz a cópia explicitamente.</p><button class="primary" data-act="saveCfg"'+(!S.cfgDirty||!validCfg()?' disabled':'')+'>Salvar padrões e limites</button><p class="help" role="status">'+(S.cfgDirty?'Alterações não salvas.':S.message==='cfg'?'Padrões salvos nesta sessão.':'Nenhuma alteração pendente.')+'</p>'+(!validCfg()?'<p class="error-message">Revise os valores e limites dos campos.</p>':'')+'</aside></div>';}
function validCfg(){const c=S.cfg;return validPolicy(c)&&Object.values(c.custom).every(validPolicy)&&Number.isInteger(c.batch)&&c.batch>=1&&c.batch<=10000&&c.reserve>=0.0625&&c.reserve<=10000&&c.quota>=32&&c.quota<=100000&&c.savings>=0&&c.savings<=90&&c.kib>=0&&c.kib<=100000&&Number.isInteger(c.retention)&&c.retention>=0&&c.retention<=3650;}
function openDialog(title,body,action,needsAck=false){returnFocus=document.activeElement;$('confirmation').innerHTML='<h2 id="dialogTitle">'+title+'</h2>'+body+(needsAck?check('Entendo que não poderei restaurar nem regenerar a partir destes originais.','id="dialogAck"',false):'')+'<div class="btn-row"><button data-act="closeDialog">Voltar sem alterar</button><button '+(needsAck?'class="danger" disabled':'class="primary"')+' data-act="confirmDialog" data-confirm="'+action+'">'+(action==='purge'?'Remover permanentemente':action==='auto'?'Autorizar e salvar':action==='defaults'?'Usar estes padrões':'Restaurar este original')+'</button></div>';$('confirmation').showModal();}
function closeDialog(){$('confirmation').close();returnFocus?.focus({preventScroll:true});}
function restoreReview(id,recovery=false){const h=S.history.find(h=>h.id===id);if(activeExec()||!h||!h.active||(!recovery&&h.status!=='available'))return;dialogData={id,recovery};openDialog('Restaurar este original?', '<p><strong>'+esc(itemName(h.item))+' · '+h.slot+'</strong></p><p>'+h.fmt+' · '+h.dim+' · '+size(h.original)+'</p><p class="help">A transação ativa '+h.id+' será usada, com verificação de integridade e da referência. Isso não altera a automação. Nesta bancada, toda a evidência é simulada.</p>','restore');}
function purgeReview(){const ids=purgeIds(),hs=eligible().filter(h=>ids.includes(h.id));if(activeExec()||!hs.length)return;dialogData={ids:hs.map(h=>h.id)};openDialog('Remover '+hs.length+' '+plural(hs.length,'original','originais')+' permanentemente?', '<p>Alcance: <strong>somente '+hs.length+' '+plural(hs.length,'original listado','originais listados')+'</strong>. Liberação estimada: <strong>'+size(hs.reduce((n,h)=>n+h.original,0))+'</strong>.</p><ul>'+hs.map(h=>'<li>'+esc(itemName(h.item))+' · '+h.slot+' · '+size(h.original)+'</li>').join('')+'</ul><p class="help">A imagem convertida permanece. Originais incertos ou que deixarem de ser elegíveis serão preservados.</p>','purge',true);}
document.addEventListener('click',e=>{const b=e.target.closest('[data-act]');if(!b||b.disabled)return;const a=b.dataset.act;
  if(a==='go'||a==='tab'){go(b.dataset.value);return;}
  if(a==='analyse'){analyse();return;}
  if(a==='editDraft'){S.step='draft';render();focus('manual-quality');return;}
  if(a==='showResults'){S.step='results';render();focus('resultadoAnalise');return;}
  if(a==='defaults'){openDialog('Usar os padrões salvos?','<p>Substitui somente os ajustes de codificação, os personalizados por tipo e o limite do rascunho. Alcance, tipos selecionados e preservação continuam como estão.</p>','defaults');return;}
  if(a==='allRows'){S.selection=S.analysis.rows.filter(r=>r.proposed).map(r=>r.id);render();announce(S.selection.length+' '+plural(S.selection.length,'proposta selecionada','propostas selecionadas')+'.');return;}
  if(a==='review'){createReview();return;}
  if(a==='backResults'){S.step='results';S.exec=null;go('simular');return;}
  if(a==='apply'){startExecution();return;}
  if(a==='cancel'){cancelExecution();return;}
  if(a==='newRun'){S.exec=null;S.step='draft';go('simular');return;}
  if(a==='editType'){const k=b.dataset.owner+b.dataset.id;S.editTypes[k]=!S.editTypes[k];render();return;}
  if(a==='restore'){restoreReview(b.dataset.id);return;}
  if(a==='recover'){restoreReview('h4',true);return;}
  if(a==='purgeReview'){purgeReview();return;}
  if(a==='purgeAll'){S.purge=eligible().map(h=>h.id);render();announce(S.purge.length+' '+plural(S.purge.length,'original selecionado','originais selecionados')+'. Nada foi removido.');return;}
  if(a==='saveCfg'){if(!validCfg())return;S.defaults=copy(S.cfg);S.cfgDirty=false;S.message='cfg';if(S.analysis){S.analysis.stale=true;S.review=null;S.selection=[];}render();announce('Padrões salvos. Rascunho e automação preservados.');return;}
  if(a==='saveAuto'){if(S.auto.mode==='apply'&&S.auto.storage==='remover'){openDialog('Autorizar remoção na automação?','<p>Somente a automação: '+(S.auto.scope==='filmes'?'Filmes':'Séries')+' · qualidade '+S.auto.quality+'. Execuções futuras poderão remover originais após verificação. Seu rascunho manual não autoriza esta ação.</p>','auto',true);}else saveAuto();return;}
  if(a==='closeDialog'){closeDialog();return;}
  if(a==='confirmDialog'){
    const action=b.dataset.confirm;if(['purge','auto'].includes(action)&&!$('dialogAck')?.checked)return;
    if(action==='restore'){const h=S.history.find(h=>h.id===dialogData.id);if(!activeExec()&&h?.active&&(h.status==='available'||dialogData.recovery)){h.status='restored';const image=S.images.find(f=>f.item===h.item&&f.slot===h.slot);if(image)Object.assign(image,{state:h.shared||image.shared?'shared':'source',fmt:h.fmt,source:h.original,original:h.original,dim:h.dim,policy:null});if(dialogData.recovery)S.scenario='normal';S.message='restored';S.purge=S.purge.filter(x=>x!==h.id);imagesChanged();}}
    if(action==='purge'){if(activeExec())return;for(const h of eligible())if(dialogData.ids.includes(h.id)){h.status='removed';removeImageOriginal(h);}S.purge=S.purge.filter(x=>!dialogData.ids.includes(x));S.message='purged';imagesChanged();}
    if(action==='auto')saveAuto(false);
    if(action==='defaults'){for(const k of Object.keys(BASE))S.draft[k]=S.defaults[k];S.draft.custom=copy(S.defaults.custom);S.draft.batch=S.defaults.batch;invalidate();}
    closeDialog();render();if(action==='restore'){const evidence=$('evidence-'+dialogData.id);if(evidence){evidence.open=true;evidence.querySelector('summary').focus();}}else if(action==='purge')focus('historyTitle');else if(action==='auto')focus('autoTitle');else if(action==='defaults')focus('simTitle');announce(action==='purge'?'Remoção sintética concluída.':action==='restore'?'Original restaurado no cenário.':'Alteração confirmada.');return;
  }
  if(a==='reset'){initial();location.hash='#/p2/paginas/simular';render(true);}
});
function saveAuto(repaint=true){S.auto.dirty=false;S.autoSaved=copy(S.auto);S.message='auto';if(repaint){render();focus('autoTitle');}announce('Automação salva. Rascunho manual preservado.');}
function fieldValue(f){return f.type==='checkbox'?f.checked:f.type==='number'?(f.value===''?NaN:Number(f.value)):f.value;}
// Keep typing controls mounted. Dependent summaries refresh on committed change.
document.addEventListener('input',e=>{const f=e.target;if(f.matches('[data-search]')){S.search=f.value;$('itemChoices').innerHTML=itemChoices();return;}if(!f.matches('input[type=number]'))return;assignField(f,false);if(f.hasAttribute('data-draft')||f.hasAttribute('data-policy')&&f.dataset.owner==='manual')invalidate();refreshNumericFeedback();});
function refreshNumericFeedback(){
  // Do not replace buttons between pointerdown (blur/change) and click. Numeric
  // editing updates only derived text and disabled states, keeping every control mounted.
  const template=document.createElement('template');
  template.innerHTML=S.area==='simular'?viewDraft():S.area==='configuracoes'?viewCfg():S.area==='automacao'?viewAuto():'';
  const derived=['.summary-line','[role="status"]','.type-row .choice small','.type-row>div>p.help'];
  for(const selector of derived){const old=[...$('conteudo').querySelectorAll(selector)],fresh=[...template.content.querySelectorAll(selector)];old.forEach((node,i)=>{if(fresh[i])node.innerHTML=fresh[i].innerHTML;});}
  for(const act of ['analyse','saveCfg','saveAuto']){const button=$('conteudo').querySelector('[data-act="'+act+'"]'),next=template.content.querySelector('[data-act="'+act+'"]');if(button&&next)button.disabled=next.disabled;}
  const oldError=$('conteudo').querySelector('.summary-panel .error-message'),newError=template.content.querySelector('.summary-panel .error-message');
  if(oldError&&!newError)oldError.remove();else if(oldError&&newError)oldError.textContent=newError.textContent;else if(newError)$('conteudo').querySelector('.summary-panel')?.append(newError.cloneNode(true));
}
function assignField(f,repaint=true){const v=fieldValue(f);if(f.dataset.draft){S.draft[f.dataset.draft]=v;if(repaint)invalidate();}
  else if(f.dataset.cfg){S.cfg[f.dataset.cfg]=v;S.cfgDirty=true;}
  else if(f.dataset.auto){S.auto[f.dataset.auto]=v;S.auto.dirty=true;}
  else if(f.dataset.policy){const owner=f.dataset.owner==='cfg'?S.cfg:S.draft;owner.custom[f.dataset.id][f.dataset.policy]=v;if(f.dataset.owner==='cfg')S.cfgDirty=true;else invalidate();}
  if(repaint)render();
}
document.addEventListener('change',e=>{const f=e.target;
  if(f.id==='dialogAck'){$('confirmation').querySelector('[data-act=confirmDialog]').disabled=!f.checked;return;}
  if(f.id==='shell'){location.hash='#/p2/'+f.value+'/'+S.area;return;}
  if(f.id==='areaMenu'){go(f.value);return;}
  if(f.id==='scenario'){setScenario(f.value);return;}
  if(f.matches('[data-draft],[data-cfg],[data-auto],[data-policy]')){if(f.type==='number'){assignField(f,false);refreshNumericFeedback();}else assignField(f);return;}
  if(f.dataset.lib){const a=S.draft.libs;f.checked?a.push(f.dataset.lib):a.splice(a.indexOf(f.dataset.lib),1);invalidate();render();return;}
  if(f.dataset.item){const a=S.draft.items;f.checked?a.push(f.dataset.item):a.splice(a.indexOf(f.dataset.item),1);invalidate();render();return;}
  if(f.dataset.type){S.draft.types[f.dataset.type]=f.checked;invalidate();render();return;}
  if(f.dataset.autoType){S.auto.types[f.dataset.autoType]=f.checked;S.auto.dirty=true;render();return;}
  if(f.dataset.custom){const obj=f.dataset.owner==='cfg'?S.cfg:S.draft;if(f.checked)obj.custom[f.dataset.custom]=Object.fromEntries(Object.keys(BASE).map(k=>[k,obj[k]]));else delete obj.custom[f.dataset.custom];if(f.dataset.owner==='cfg')S.cfgDirty=true;else invalidate();render();return;}
  if(f.dataset.row){if(S.analysis.stale)return;f.checked?S.selection.push(f.dataset.row):S.selection=S.selection.filter(x=>x!==f.dataset.row);render();announce(S.selection.length+' '+plural(S.selection.length,'imagem selecionada','imagens selecionadas')+'.');return;}
  if(f.dataset.ack){if(S.review){S.review[f.dataset.ack]=f.checked;render();}return;}
  if(f.dataset.purge){f.checked?S.purge.push(f.dataset.purge):S.purge=S.purge.filter(x=>x!==f.dataset.purge);render();return;}
});
document.addEventListener('keydown',e=>{const tab=e.target.closest('[role=tab]');if(!tab||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const i=AREAS.findIndex(x=>x[0]===tab.dataset.value),next=e.key==='Home'?0:e.key==='End'?AREAS.length-1:(i+(e.key==='ArrowRight'?1:-1)+AREAS.length)%AREAS.length;location.hash='#/p2/abas/'+AREAS[next][0];});
$('confirmation').addEventListener('close',()=>returnFocus?.focus({preventScroll:true}));
function setScenario(value){S.scenario=value;
  if(value==='waitNext'){render();return;}
  if(value==='normal'&&S.exec?.phase==='waiting'){S.exec.phase='inventory';go('executar');schedule();return;}
  if(value==='waiting'&&activeExec()){clearTimeout(timer);S.exec.phase='waiting';go('executar');render();announce('Operação aguardando metadata.');return;}
  if(['empty','unavailable'].includes(value))invalidate();
  if(['waiting','partial'].includes(value)){
  clearTimeout(timer);const rows=FIXTURES.slice(0,value==='partial'?4:2).map(r=>({...copy(r),proposed:true,action:r.state==='converted'?'regenerate':'convert',policy:copy(BASE)}));
  S.exec={id:value==='partial'?'exec-exemplo-parcial':'exec-exemplo-espera',phase:value==='partial'?'done':'waiting',draft:copy(S.draft),rows,expired:[],results:value==='partial'?rows.map((r,i)=>({...r,result:i<2?'done':i===2?'skipped':'failed'})):[]};go('executar');
  }else if(['recovery','conflict','changed'].includes(value)){if(S.exec&&!activeExec())S.exec=null;go('executar');}
  else if(value==='tasks')go('automacao');else{if(value==='unavailable')S.draft.scope='itens';S.step='draft';go('simular');}render();
}
addEventListener('hashchange',()=>{const old=S.area,onTab=document.activeElement?.getAttribute('role')==='tab';route();render(old!==S.area&&!onTab);if(onTab)$('tab-'+S.area)?.focus();});
initial();route();render();
